import { slugify, type Palette } from '../core/palette'
import { TARGETS, type Target } from './index'

export type OutputFile = { target: Target; path: string; contents: string; setup: string }

export function renderAll(palette: Palette, targets: Target[] = TARGETS): OutputFile[] {
  const slug = slugify(palette.name)
  return targets.map((target) => ({
    target,
    path: target.path(slug),
    contents: target.render(palette, slug),
    setup: target.setup(slug),
  }))
}

// Shipped alongside the generated files so the palette can be re-imported
// into the web app or fed to the CLI later
export function paletteJson(palette: Palette): string {
  return JSON.stringify(palette, null, 2) + '\n'
}

export function setupNotes(palette: Palette, files: OutputFile[]): string {
  return [
    `${palette.name}, generated by theme-forge`,
    '',
    'Copy each folder here into ~/.config/ (full paths are listed below).',
    'None of these replace your existing config; each needs one line to switch it on:',
    '',
    ...files.flatMap((f) => [`${f.target.name}`, `  ~/${f.path}`, `  ${f.setup}`, '']),
  ].join('\n')
}
